  t+=w(r.ablauf.text);
  t+=r.agri.reduce((a,x)=>a+w(x),0);
  t+=r.besonderheiten.reduce((a,x)=>a+w(x.titel)+w(x.text),0);
  t+=r.faq.reduce((a,x)=>a+w(x.q)+w(x.a),0);
  console.log(n,"seo",r.seoTitel.length,"desc",r.beschreibung.length,"words",t,"quellen",r.quellen.length,"faq",r.faq.length);
}
